package io.mycinema.tv;

import android.app.Activity;
import android.app.Instrumentation;
import android.content.Context;
import android.content.Intent;
import android.graphics.Bitmap;
import android.os.Bundle;
import android.view.KeyEvent;
import android.view.View;
import android.view.ViewGroup;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.EditText;
import android.widget.GridView;
import android.widget.TextView;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;

/** Uses actual DPAD/confirm/back/menu events; programmatic focus only locates a test's starting control. */
final class RemoteScenario {
    private final Instrumentation test;private Context context;private MainActivity activity;private final List<String> checks=new ArrayList<>();private int keyEvents;
    RemoteScenario(Instrumentation test){this.test=test;}
    private void check(boolean condition,String label){if(!condition)throw new AssertionError(label);checks.add(label);}
    private void idle()throws Exception{test.waitForIdleSync();Thread.sleep(180);}
    private void key(int code)throws Exception{keyEvents++;test.sendKeyDownUpSync(code);idle();}
    private void nav(int id)throws Exception{test.runOnMainSync(()->activity.findViewById(id).requestFocus());key(KeyEvent.KEYCODE_DPAD_CENTER);}
    private View text(View root,String wanted){if(root instanceof TextView&&((TextView)root).getText().toString().startsWith(wanted))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=text(((ViewGroup)root).getChildAt(i),wanted);if(found!=null)return found;}return null;}
    private int editors(AccessibilityNodeInfo root){if(root==null)return 0;int result="android.widget.EditText".contentEquals(root.getClassName())?1:0;for(int i=0;i<root.getChildCount();i++)result+=editors(root.getChild(i));return result;}
    private AccessibilityNodeInfo action(AccessibilityNodeInfo root,String label){if(root==null)return null;if(root.isClickable()&&root.getText()!=null&&root.getText().toString().equals(label))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=action(root.getChild(i),label);if(found!=null)return found;}return null;}
    private void startControl(String label)throws Exception{test.runOnMainSync(()->{View target=text(activity.getWindow().getDecorView(),label);if(target==null||!target.requestFocus())throw new AssertionError("starting control "+label);});idle();}
    private void shot(String name)throws Exception{Bitmap image=test.getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(context.getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    void run(String run){context=test.getTargetContext();Bundle result=new Bundle();JSONObject report=new JSONObject();JSONObject snapshot=null;String oldHistory=context.getSharedPreferences("search-history",0).getString("queries","[]"),oldMirror=context.getSharedPreferences("app-updates",0).getString("mirror","auto");try(Library library=new Library(context)){
        snapshot=library.snapshot();for(Library.Item old:library.list("","","","","recent"))library.remove(old.id());
        List<String> ids=new ArrayList<>();for(int n=0;n<24;n++){JSONObject movie=new JSONObject();Json.put(movie,"title",String.format(java.util.Locale.ROOT,"遥控测试%02d",n));Json.put(movie,"mediaType",n<2?"tv":"movie");Json.put(movie,"externalId","");if(n<2)Json.put(movie,"series",TmdbClient.series("remote:series","遥控系列",n+1));ids.add(library.saveCandidate(movie).id());}
        context.getSharedPreferences("MainActivity",0).edit().putBoolean("folderView",false).commit();test.setInTouchMode(false);activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));idle();nav(R.id.nav_library);
        GridView grid=(GridView)activity.findViewById(R.id.library_grid);key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_DOWN);int selected=grid.getSelectedItemPosition();check(selected>0,"DPAD traverses real poster grid");key(KeyEvent.KEYCODE_DPAD_CENTER);check(activity.findViewById(R.id.detail_title)!=null,"confirm opens selected film");key(KeyEvent.KEYCODE_BACK);grid=(GridView)activity.findViewById(R.id.library_grid);check(grid.getSelectedItemPosition()==selected&&grid.hasFocus(),"back restores exact selected poster and focus");
        key(KeyEvent.KEYCODE_MENU);key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"menu search offers remote choices without keyboard");key(KeyEvent.KEYCODE_DPAD_CENTER);key(KeyEvent.KEYCODE_DPAD_CENTER);check(((GridView)activity.findViewById(R.id.library_grid)).getAdapter().getCount()==1,"existing-title collection search needs no text input");startControl("搜索");key(KeyEvent.KEYCODE_DPAD_DOWN);check(activity.findViewById(R.id.library_grid).hasFocus(),"single-result grid reached from toolbar");key(KeyEvent.KEYCODE_DPAD_CENTER);check(activity.findViewById(R.id.detail_title)!=null,"one confirm opens the single filtered result");key(KeyEvent.KEYCODE_BACK);
        key(KeyEvent.KEYCODE_MENU);key(KeyEvent.KEYCODE_DPAD_CENTER);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);check(((GridView)activity.findViewById(R.id.library_grid)).getAdapter().getCount()==24,"search reset reachable through DPAD menu");
        // Start from selected poster, then move only with the remote inside detail/score menus.
        test.runOnMainSync(()->activity.findViewById(R.id.library_grid).requestFocus());key(KeyEvent.KEYCODE_DPAD_CENTER);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"quick rating contains no editable keyboard field");key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);
        String current="";for(Library.Item item:library.list("","","","","recent"))if(!item.entry.isNull("personalRating")){current=item.id();check(item.entry.optDouble("personalRating")==8.5,"8.5 rating saved by direction and confirm keys");}check(!current.isEmpty(),"rating path committed to real SQLite");check(activity.getCurrentFocus() instanceof TextView&&((TextView)activity.getCurrentFocus()).getText().toString().startsWith("个人评分"),"rating save keeps focus on rating action");
        key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_CENTER);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);check(library.get(current).status().equals("watched"),"watch state changed without opening editor");shot("remote-rating");
        key(KeyEvent.KEYCODE_MENU);key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);EditText input=(EditText)activity.findViewById(R.id.search_query);check(input!=null&&!input.getShowSoftInputOnFocus(),"focusing search field does not automatically open IME");SearchHistory history=new SearchHistory(context);history.clear();for(int n=0;n<15;n++)history.add("历史片名"+n);history.add("历史片名12");check(history.list().size()==12&&history.list().get(0).equals("历史片名12"),"recent searches persist bounded and deduplicated");startControl("最近搜索");key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"recent title picker does not require keyboard");key(KeyEvent.KEYCODE_BACK);
        nav(R.id.nav_settings);startControl("更新来源：");key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"built-in mirror selection has no address entry");for(int n=0;n<3;n++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);check(context.getSharedPreferences("app-updates",0).getString("mirror","").equals("https://ghfast.top/"),"GHFast selected and saved using DPAD");shot("remote-mirrors");probeMirrors(report);
        // Keep two seasons and one film to verify group selection and automatic folder naming.
        for(int i=3;i<ids.size();i++)library.remove(ids.get(i));nav(R.id.nav_library);key(KeyEvent.KEYCODE_MENU);for(int n=0;n<3;n++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"series bulk picker has no text fields");
        // Find the series row in the native list, move to it using DPAD and toggle it.
        AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();AccessibilityNodeInfo row=findContaining(root,"遥控系列 · 2 部");check(row!=null,"series picker combines both seasons into one checkbox");for(int move=0;move<4&&!row.isSelected();move++){key(KeyEvent.KEYCODE_DPAD_DOWN);row=findContaining(test.getUiAutomation().getRootInActiveWindow(),"遥控系列 · 2 部");}check(row!=null&&row.isSelected(),"DPAD selects the series checkbox row");key(KeyEvent.KEYCODE_DPAD_CENTER);AccessibilityNodeInfo save=action(test.getUiAutomation().getRootInActiveWindow(),"选择文件夹");check(save!=null&&save.performAction(AccessibilityNodeInfo.ACTION_FOCUS),"folder destination button focusable");key(KeyEvent.KEYCODE_DPAD_CENTER);check(editors(test.getUiAutomation().getRootInActiveWindow())==0,"suggested folder title avoids typing");key(KeyEvent.KEYCODE_DPAD_CENTER);JSONObject folder=library.get(ids.get(0)).film.optJSONObject("series").optJSONObject("franchise");check(folder!=null&&folder.optString("title").equals("遥控系列宇宙")&&library.get(ids.get(1)).film.optJSONObject("series").optJSONObject("franchise")!=null,"one group selection files all seasons under suggested universe name");
        nav(R.id.nav_home);key(KeyEvent.KEYCODE_BACK);key(KeyEvent.KEYCODE_DPAD_CENTER);check(!activity.isFinishing(),"exit confirmation defaults to cancel");Json.put(report,"result","passed");result.putString("result","passed");
    }catch(Throwable error){try{shot("remote-failure");}catch(Exception ignored){}Json.put(report,"result","failed");Json.put(report,"error",error.toString());result.putString("result","failed");result.putString("error",error.toString());}finally{if(activity!=null)test.runOnMainSync(activity::finish);if(snapshot!=null)try(Library library=new Library(context)){library.restore(snapshot);}catch(Exception ignored){}context.getSharedPreferences("search-history",0).edit().putString("queries",oldHistory).commit();context.getSharedPreferences("app-updates",0).edit().putString("mirror",oldMirror).commit();context.getSharedPreferences("MainActivity",0).edit().putBoolean("folderView",false).commit();}
        Json.put(report,"checks",new JSONArray(checks));Json.put(report,"remoteKeyEvents",keyEvents);Json.put(report,"buildRun",run);Json.put(report,"apiLevel",android.os.Build.VERSION.SDK_INT);Json.put(report,"textInputUsedForQuickActions",false);Json.put(report,"physicalRemoteVerified",false);Json.put(report,"voiceServiceVerified",false);try(FileOutputStream output=new FileOutputStream(new File(context.getFilesDir(),"remote-report.json"))){output.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}catch(Exception error){result.putString("result","failed");}test.finish("passed".equals(result.getString("result"))?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
    private void probeMirrors(JSONObject report)throws Exception{JSONArray results=new JSONArray();TvUpdates service=new TvUpdates(context);java.lang.reflect.Field field=TvUpdates.class.getDeclaredField("http");field.setAccessible(true);okhttp3.OkHttpClient http=((okhttp3.OkHttpClient)field.get(service)).newBuilder().callTimeout(12,java.util.concurrent.TimeUnit.SECONDS).build();String cert;try(java.io.InputStream input=context.getAssets().open("update-signing.json")){cert=Json.object(new String(TmdbClient.read(input,16384),StandardCharsets.UTF_8)).getString("certificatePem");}JSONArray presets=TvUpdates.mirrorPresets(context);for(int i=0;i<presets.length();i++){JSONObject mirror=presets.getJSONObject(i),entry=new JSONObject();Json.put(entry,"mirror",Json.text(mirror,"url"));try(okhttp3.Response response=http.newCall(new okhttp3.Request.Builder().url(Json.text(mirror,"url")+"https://raw.githubusercontent.com/StQuasimodo/Media-Library/main/updates/tv-preview.json").build()).execute()){if(response.code()!=200)throw new java.io.IOException();TvUpdates.verify(new String(TmdbClient.read(response.body().byteStream(),65536),StandardCharsets.UTF_8),"preview",cert);Json.put(entry,"signedManifestHttpsVerified",true);}catch(Exception error){Json.put(entry,"signedManifestHttpsVerified",false);Json.put(entry,"diagnosticClass",error.getClass().getSimpleName());if(error.getCause()!=null)Json.put(entry,"causeClass",error.getCause().getClass().getSimpleName());}results.put(entry);}service.close();Json.put(report,"publicMirrorChecks",results);javax.net.ssl.X509TrustManager trust=UpdateTls.trust(context);java.security.cert.X509Certificate signing=(java.security.cert.X509Certificate)java.security.cert.CertificateFactory.getInstance("X.509").generateCertificate(new java.io.ByteArrayInputStream(cert.getBytes(StandardCharsets.US_ASCII)));boolean rejected=false;try{trust.checkServerTrusted(new java.security.cert.X509Certificate[]{signing},"RSA");}catch(java.security.cert.CertificateException expected){rejected=true;}check(rejected,"update TLS still rejects an unrelated self-signed certificate");}
    private AccessibilityNodeInfo findContaining(AccessibilityNodeInfo root,String text){if(root==null)return null;if(root.getText()!=null&&root.getText().toString().contains(text)&&root.isClickable())return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo found=findContaining(root.getChild(i),text);if(found!=null)return found;}return null;}
}
